/* Additional browser-local services. Loaded before order.js; functions run after its state is ready. */
const requestTypes=['parcel','errands','lift','multi'];
const stopKinds={buy:'Pabili / shopping',pickup:'Pick up an item',dropoff:'Drop off an item'};
function requestName(s){
  if(s?.type==='lift')return 'Cartman LIFT · '+(s.vehicle==='tricycle'?'Tricycle':'Motorcycle');
  return {parcel:'Parcel delivery',errands:'Pabili & errands',multi:'Multi-stop errands'}[s?.type]||'Service request';
}
function requestStatus(o){
  if(o.service?.type==='lift')return ['Requested','Finding driver','Ride in progress','Arrived'][o.stage];
  if(o.service?.type==='multi')return o.stage===3?'Completed':`${o.completedStops||0} / ${o.service.stops.length} stops complete`;
  return ['Confirmed','Preparing','On the way','Delivered'][o.stage];
}
function requestDetails(s){
  const route=`<dl class="request-route"><div><dt>${s.type==='lift'?'Pickup':'First pickup'}</dt><dd>${esc(s.pickup)}</dd></div><div><dt>${s.type==='lift'?'Destination':'Final destination'}</dt><dd>${esc(s.dropoff)}</dd></div></dl>`;
  if(s.type==='lift')return `<h3>${requestName(s)}</h3>${route}<p>${esc(s.passengers)} ${Number(s.passengers)===1?'passenger':'passengers'} · ${esc(s.distance)} km sample distance</p><div class="summary-item"><span>Sample base fare</span><strong>${peso(s.base)}</strong></div><div class="summary-item"><span>Sample distance component</span><strong>${peso(s.distanceFee)}</strong></div>${s.notes?`<p>${esc(s.notes)}</p>`:''}`;
  if(s.type==='multi')return `<h3>Multi-stop errands</h3><ol class="review-stops">${s.stops.map((stop,i)=>`<li><span class="stop-number">${i+1}</span><div><strong>${esc(stopKinds[stop.kind]||'Errand')}</strong><p>${esc(stop.address)}</p><small>${esc(stop.task)}</small>${stop.budget>0?`<small>Shopping budget: ${peso(stop.budget)}</small>`:''}</div></li>`).join('')}</ol><p><strong>Final destination</strong><br>${esc(s.dropoff)}</p><p>Shopping budget: <strong>${peso(s.budget)}</strong> · separate from service fees.</p>`;
  return `<h3>${requestName(s)}</h3><p>${esc(s.details)}</p>${route}${s.size?`<p>Parcel size: ${esc(s.size)}</p>`:''}${s.budget?`<p>Shopping budget: ${peso(Number(s.budget))} (excluded)</p>`:''}`;
}
function liftPage(){
  document.title='Cartman LIFT · Ride demo';
  const draft=serviceDraft?.type==='lift'?serviceDraft:null;
  shell(`<a class="back-link" href="#/">← Explore services</a><div class="service-layout lift-layout"><section><span class="eyebrow">CARTMAN LIFT</span><h1>Your ride.<br>Your choice.</h1><p class="lead">Choose a motorcycle or tricycle, add your pickup and destination, and preview a Cartman LIFT ride.</p><img class="service-illustration lift-photo" src="assets/lift-service-v2.webp" alt="A Cartman LIFT scooter and covered Philippine sidecar tricycle" width="900" height="600"><div class="service-facts"><span>${svg('pin')} Pickup to destination</span><span>${svg('user')} Choose your ride</span></div><p class="disclosure">Demo only. Vehicle availability, passenger capacity, coverage and final fares will be confirmed before launch.</p></section><form id="lift-form" class="form-panel"><h2>Where are you headed?</h2><fieldset class="vehicle-field"><legend>Choose your vehicle</legend><div class="vehicle-options">${[['motorcycle','bike','Motorcycle','A solo passenger ride'],['tricycle','trike','Tricycle','A ride with a sidecar']].map(([value,i,label,note])=>`<label class="vehicle-option"><input type="radio" name="vehicle" value="${value}" ${(draft?.vehicle||'motorcycle')===value?'checked':''}>${svg(i)}<strong>${label}</strong><small>${note}</small></label>`).join('')}</div></fieldset><label>Pickup location<input name="pickup" autocomplete="street-address" maxlength="180" required value="${esc(draft?.pickup||'')}" placeholder="Building, street, barangay"></label><label>Destination<input name="dropoff" maxlength="180" required value="${esc(draft?.dropoff||delivery)}" placeholder="Where would you like to go?"></label><div class="ride-field-row"><label>Passengers<select name="passengers" id="ride-passengers"></select></label><label>Sample distance<select name="distance"><option value="2">2 km</option><option value="5">5 km</option><option value="10">10 km</option></select></label></div><label>Pickup notes <span>(optional)</span><textarea name="notes" rows="2" maxlength="400" placeholder="Landmark or meeting point">${esc(draft?.notes||'')}</textarea></label><div class="service-estimate" aria-live="polite"><span>Illustrative ride fare<small>Sample values · no payment collected</small></span><strong id="ride-estimate"></strong></div><button class="primary full">Review demo ride ${svg('arrow')}</button></form></div>`);
  const form=q('#lift-form');if(draft)form.elements.distance.value=String(draft.distance);
  function update(){const type=form.elements.vehicle.value;const passengers=q('#ride-passengers');const previous=passengers.value||String(draft?.passengers||1);passengers.innerHTML=(type==='motorcycle'?[1]:[1,2,3]).map(n=>`<option value="${n}">${n} ${n===1?'passenger':'passengers'}</option>`).join('');passengers.value=type==='motorcycle'?'1':previous;if(!passengers.value)passengers.value='1';const base=type==='motorcycle'?49:69;const distanceFee=Number(form.elements.distance.value)*(type==='motorcycle'?12:15);q('#ride-estimate').textContent=peso(base+distanceFee)}
  form.onchange=update;update();
  form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));const base=data.vehicle==='motorcycle'?49:69;const distanceFee=Number(data.distance)*(data.vehicle==='motorcycle'?12:15);serviceDraft={...data,type:'lift',base,distanceFee,fee:base+distanceFee,details:`${data.vehicle==='motorcycle'?'Motorcycle':'Tricycle'} ride · ${data.passengers} passenger(s) · ${data.distance} km sample distance`};persist('service-draft',serviceDraft);location.hash='/checkout'};
}
function multiPage(){
  document.title='Multi-stop errands · Cartman PH';
  const draft=serviceDraft?.type==='multi'?serviceDraft:null;
  let stops=draft?.stops?.map(s=>({...s}))||[{kind:'buy',address:'',task:'',budget:0},{kind:'pickup',address:'',task:'',budget:0}];
  shell(`<a class="back-link" href="#/">← Explore services</a><div class="service-layout multi-layout"><section><span class="eyebrow">MORE STOPS. ONE REQUEST.</span><h1>More errands.<br>One request.</h1><p class="lead">Pabili at the tindahan, a pickup at the bakery, a parcel to drop off. Put your tasks together in the order you want them done.</p><img class="service-illustration multi-photo" src="assets/multi-errands-v2.webp" alt="Bakery bread, groceries, a parcel and documents gathered for multiple errands" width="600" height="400"><p class="disclosure">Plan 2–5 stops, followed by your final destination. Stops follow your chosen order. Shopping budgets are separate from the service fee.</p></section><form id="multi-form" class="form-panel"><h2>Plan your errands</h2><p class="disclosure">Add a task and address for every stop. Reorder stops with the arrow buttons.</p><div id="errand-stops"></div><button type="button" id="add-stop" class="secondary full">+ Add another stop</button><label class="final-destination">Final destination<input name="destination" required maxlength="180" value="${esc(draft?.dropoff||delivery)}" placeholder="Where should everything end up?"></label><div class="service-estimate" aria-live="polite"><span>Illustrative service fee<small id="multi-fee-note"></small></span><strong id="multi-estimate"></strong></div><p class="disclosure">Demo rate: ₱89 for the first stop + ₱35 per additional stop. Purchases are excluded. No real errands are dispatched.</p><button class="primary full">Review demo errands ${svg('arrow')}</button></form></div>`);
  function sync(){stops=stops.map((s,i)=>({kind:q(`[name="kind-${i}"]`).value,address:q(`[name="address-${i}"]`).value,task:q(`[name="task-${i}"]`).value,budget:q(`[name="kind-${i}"]`).value==='buy'?Number(q(`[name="budget-${i}"]`).value||0):0}))}
  function draw(focusIndex){q('#errand-stops').innerHTML=stops.map((s,i)=>`<fieldset class="errand-stop"><legend>Stop ${i+1}</legend><div class="stop-actions"><button type="button" data-move="${i}" data-direction="-1" aria-label="Move stop ${i+1} up" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-direction="1" aria-label="Move stop ${i+1} down" ${i===stops.length-1?'disabled':''}>↓</button><button type="button" data-remove="${i}" aria-label="Remove stop ${i+1}" ${stops.length<=2?'disabled':''}>×</button></div><label>Task type<select name="kind-${i}">${Object.entries(stopKinds).map(([v,label])=>`<option value="${v}" ${v===s.kind?'selected':''}>${label}</option>`).join('')}</select></label><label>Stop ${i+1} address<input name="address-${i}" required maxlength="180" value="${esc(s.address)}" placeholder="Store, building, street, barangay"></label><label>What should we do here?<textarea name="task-${i}" required maxlength="500" rows="2" placeholder="Items, quantities, or pickup instructions">${esc(s.task)}</textarea></label><label class="stop-budget" ${s.kind!=='buy'?'hidden':''}>Shopping budget (₱)<input name="budget-${i}" type="number" min="0" max="10000" step="1" value="${s.budget||0}"></label></fieldset>`).join('');
    q('#add-stop').disabled=stops.length>=5;q('#add-stop').textContent=stops.length>=5?'Maximum 5 stops':'+ Add another stop';q('#multi-estimate').textContent=peso(89+(stops.length-1)*35);q('#multi-fee-note').textContent=`${stops.length} stops · purchases excluded`;
    document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{sync();stops.splice(Number(b.dataset.remove),1);draw()});
    document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{sync();const i=Number(b.dataset.move),j=i+Number(b.dataset.direction);[stops[i],stops[j]]=[stops[j],stops[i]];draw(j)});
    stops.forEach((s,i)=>q(`[name="kind-${i}"]`).onchange=()=>{sync();draw()});
    if(focusIndex!==undefined)q(`[name="address-${focusIndex}"]`).focus();
  }
  draw();q('#add-stop').onclick=()=>{sync();if(stops.length>=5)return;stops.push({kind:'pickup',address:'',task:'',budget:0});draw(stops.length-1)};
  q('#multi-form').onsubmit=e=>{e.preventDefault();sync();serviceDraft={type:'multi',stops:stops.map(s=>({...s})),pickup:stops[0].address,dropoff:q('[name="destination"]').value,budget:stops.reduce((n,s)=>n+s.budget,0),fee:89+(stops.length-1)*35,details:`${stops.length} errands in your chosen stop order`};persist('service-draft',serviceDraft);location.hash='/checkout'};
}

function multiTracking(o){
  const s=o.service,completed=o.completedStops||0,done=o.stage===3;
  shell(`<a class="back-link" href="#/orders">← My orders</a><div class="section-top"><div><span class="eyebrow">MULTI-STOP ERRANDS · SIMULATION</span><h1>${done?'Errands done. Day made.':'Every stop, in view.'}</h1><p>${o.id} · ${esc(o.details.name)}</p></div><span class="demo-pill">SIMULATED TRACKING</span></div><div class="tracking-layout"><section class="tracking-card"><h2>${done?'All errands complete':completed===s.stops.length?'Ready for your final destination':`Next: stop ${completed+1} of ${s.stops.length}`}</h2><p>Stops follow the order you chose. Advance the demo to preview each task; no real driver is assigned.</p><ol class="timeline">${s.stops.map((stop,i)=>`<li class="${i<completed?'complete':''}"><span>${i<completed?'✓':i+1}</span><div><strong>${esc(stopKinds[stop.kind])}</strong><small>${esc(stop.address)}</small><small>${esc(stop.task)}</small></div></li>`).join('')}<li class="${done?'complete':''}"><span>${done?'✓':svg('pin')}</span><div><strong>Final destination</strong><small>${esc(s.dropoff)}</small></div></li></ol>${done?'<a href="#/" class="primary full">Plan something else →</a>':`<button class="primary full" id="advance-stops">${completed<s.stops.length?`Simulate stop ${completed+1} completed`:'Simulate final drop-off'} →</button>`}</section><aside class="form-panel"><h2>Your errands summary</h2><p><strong>${esc(o.details.name)}</strong><br>${esc(o.details.phone)}</p><p>${esc(o.details.notes||'No extra instructions.')}</p><div class="total-line"><span>Demo service fee</span><strong>${peso(o.total)}</strong></div><p>Shopping budget: <strong>${peso(s.budget)}</strong> (separate)</p><p class="disclosure">${esc(o.details.payment)} · No payment collected. Progress is saved only in this browser.</p></aside></div>`,'orders');
  if(q('#advance-stops'))q('#advance-stops').onclick=()=>{if(completed<s.stops.length){o.completedStops=completed+1;o.stage=2}else o.stage=3;persist('orders',orders);multiTracking(o);q('#main').focus({preventScroll:true})};
}
